-- -----------------------------------------------------
-- Data for table `nextage`.`questoes`
-- -----------------------------------------------------
START TRANSACTION;
USE `nextage`;
INSERT INTO `nextage`.`questoes` (`id_questao`, `id_vestibular`, `id_alternativa_correta`, `explicacao`, `enunciado`, `imagem`) VALUES (1, 1, 2, '', 'A exposição a alguns níveis sonoros pode causar lesões auditivas. Por isso, em uma indústria, são adotadas medidas preventivas de acordo com a máquina que o funcionário opera e o nível N de intensidade do som, medido em decibel (dB), a que o operário é exposto, sendo  Imagem associada para resolução da questão I a intensidade do som e I0 = 10−12 W/m2.', NULL);
INSERT INTO `nextage`.`questoes` (`id_questao`, `id_vestibular`, `id_alternativa_correta`, `explicacao`, `enunciado`, `imagem`) VALUES (2, 2, 10, NULL, 'A arte foi e ainda pode ser utilizada para criar, reforçar e disseminar ideias, valores e estereótipos, mas também pode colocá-los em discussão. A obra “Sentem para jantar”, de Gê Viana, faz parte da série “Atualizações traumáticas de Debret”, na qual o artista propõe uma revisão iconográfica da história do Brasil tendo como referência as obras de JeanBaptiste Debret, especificamente aquelas presentes em “Viagem Pitoresca e Histórica ao Brasil” (1834-1839), publicação que pautou de maneira imagética o período colonial brasileiro. Em sua revisão, Gê Viana dá continuidade ao seu projeto de análise crítica de representações históricas, produzindo releituras de algumas dessas obras, dentre as quais, a obra “Um jantar brasileiro”, do artista francês. A seguir, são reproduzidos os quadros desses dois artistas. Com base nas informações e imagens apresentadas, assinale a alternativa que corresponde à abordagem adotada por Gê Viana em sua obra “Sentem para jantar”, ao utilizar como referência a obra “Um jantar brasileiro”, de Jean-Baptiste Debret.', NULL);
INSERT INTO `nextage`.`questoes` (`id_questao`, `id_vestibular`, `id_alternativa_correta`, `explicacao`, `enunciado`, `imagem`) VALUES (3, 3, 13, NULL, 'Em humanos, o sexo é determinado pela presença dos cromossomos sexuais X e Y, que são considerados parcialmente (i) _________. A inativação de um cromossomo X é um processo aleatório e foi demonstrado que os (ii) _________ no corpús culo de Barr são inativos, o que significa que eles não serão (iii) _________. A inativação do cromossomo X é um processo de controle epigenético, que molda o funcionamento do (iv) _________ sem alterá-lo, e iguala a atividade gênica das mulheres à dos homens.', NULL);

COMMIT;


