INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (7, 2, 'Gê Viana exalta, em sua obra, especialmente as características físicas das pessoas retratadas, enquanto Debret enfatiza as relações pessoais.');
INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (8, 2, 'Gê Viana emprega, em sua obra, as mesmas técnicas e os mesmos materiais utilizados na obra de Debret, o que lhes confere grande semelhança.');
INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (9, 2, 'Gê Viana ignora aspectos relacionados a questões étnico-raciais em sua releitura da obra de Debret, focando apenas na estética visual da obra.');
INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (10, 2, 'Gê Viana busca desconstruir, em sua obra, os estereótipos étnico-raciais presentes na obra original de Debret.');
INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (11, 3, '(i) homólogos; (ii) alelos; (iii) traduzidos; (iv) código genético.');
INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (12, 3, '(i) autossomos; (ii) genes; (iii) transcritos; (iv) código genético.');
INSERT INTO `nextage`.`alternativas` (`id_alternativas`, `questoes_id_questao`, `texto`) VALUES (13, 3, '(i) homólogos; (ii) genes; (iii) transcritos; (iv) genoma.');
